<script setup lang="ts">
import {ref} from 'vue';import {api} from '../api';import AppModal from './AppModal.vue';
const props=defineProps<{kbId:number}>();const opened=ref(false),error=ref(''),form=ref<any>({}),saving=ref(false);
async function open(){error.value='';try{form.value=await api(`/api/v1/knowledge-bases/${props.kbId}/processing`);opened.value=true;}catch(e:any){error.value=e.message;}}
async function save(){saving.value=true;try{await api(`/api/v1/knowledge-bases/${props.kbId}/processing`,{method:'PUT',body:JSON.stringify(form.value)});opened.value=false;}catch(e:any){error.value=e.message;}finally{saving.value=false;}}
</script>
<template><button class="secondary" @click="open">文档处理策略</button><span class="error" v-if="error&&!opened">{{error}}</span><AppModal v-if="opened" title="文档解析与切片" @close="opened=false"><form class="form-stack" @submit.prevent="save"><p class="muted">只影响新上传、手动重建的资料；保存不会自动重建已有资料。</p><label>切片方式<select v-model="form.mode"><option value="general">通用结构分段</option><option value="parent_child">父子分段：子块检索，父块提供上下文</option></select></label><label>分段 / 父块最大字符数<input type="number" v-model.number="form.chunk_size" min="256" max="4000"></label><label>重叠字符数<input type="number" v-model.number="form.overlap" min="0" max="800"></label><label v-if="form.mode==='parent_child'">子块最大字符数<input type="number" v-model.number="form.child_size" min="128" max="1500"></label><p>PDF 跨页续段/续表、Word 顺序、Excel 表头与工作表信息保留；支持 PPTX 文本/表格、图片中英文 OCR、DXF 文字/图层/布局。</p><p class="muted">DWG 需先导出 PDF 或 DXF。图纸文字检索不等于几何、尺寸链或设计合规推理；PPTX 内嵌图片暂不单独 OCR。</p><p class="error">{{error}}</p><button class="primary" :disabled="saving">保存</button></form></AppModal></template>
